// Generates src/tokens/tokens.css and src/tokens/tokens.ts from tokens/tokens.json.
//   node scripts/build-tokens.mjs           write the files
//   node scripts/build-tokens.mjs --check   exit 1 if the committed files differ (CI)
// Generated files are never hand-edited.
import { readFileSync, writeFileSync } from "node:fs";
import { brandKey } from "./contrast-lib.mjs";

const root = new URL("../", import.meta.url);
const read = (p) => readFileSync(new URL(p, root), "utf8");

export const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

const px = (n) => (n === 0 ? "0" : `${n}px`);
const ms = (n) => `${n}ms`;

/** Theme-dependent declarations (colours, sync, brand, elevation). */
function themeVars(tokens, theme) {
  const lines = [];
  const colors = tokens.color.themes[theme];
  for (const [key, value] of Object.entries(colors)) {
    if (key.startsWith("_")) continue;
    lines.push(`--hy-color-${kebab(key)}: ${value};`);
  }
  const bk = brandKey(theme);
  lines.push(`--hy-color-primary: ${tokens.brand.primary[bk]};`);
  lines.push(`--hy-color-on-primary: ${tokens.brand.onPrimary[bk]};`);
  for (const [state, entry] of Object.entries(tokens.color.sync)) {
    if (state.startsWith("_")) continue;
    lines.push(`--hy-sync-${state}-fg: ${entry.fg[theme]};`);
    lines.push(`--hy-sync-${state}-bg: var(--hy-color-${kebab(entry.bg)});`);
  }
  const sb = tokens.color.vendorAdmin.supportSessionBanner;
  for (const part of ["bg", "fg", "border"]) {
    lines.push(`--hy-support-banner-${part}: var(--hy-color-${kebab(sb[part])});`);
  }
  const shadows = theme === "light";
  for (const [level, value] of Object.entries(tokens.elevation)) {
    if (level.startsWith("_")) continue;
    lines.push(`--hy-elevation-${level}: ${shadows ? value : "none"};`);
  }
  return lines;
}

function indented(selector, lines, indent = "") {
  return `${indent}${selector} {\n${lines.map((l) => `${indent}  ${l}`).join("\n")}\n${indent}}`;
}

export function buildCss(tokens) {
  const out = [];
  out.push(
    [
    "/*",
    " * GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand.",
    " * Themes switch with <html data-theme=\"light|dark|highContrast|kds\" data-density=\"touch|desktop\" lang=\"en|ta|ml\">.",
    " * Components use semantic variables only; no literal colours or sizes.",
    " */",
    ].join("\n"),
  );

  // Static (theme independent) variables.
  const root = [];
  const ui = tokens.typography.fontFamily;
  root.push(`--hy-font-family: ${ui.ui};`, `--hy-font-family-mono: ${ui.mono};`);
  root.push(`--hy-font-numeric: ${tokens.typography.numeric};`);
  for (const [name, s] of Object.entries(tokens.typography.scale)) {
    const n = kebab(name);
    root.push(`--hy-font-size-${n}: ${px(s.size)};`, `--hy-font-weight-${n}: ${s.weight};`);
  }
  root.push(`--hy-font-size: var(--hy-font-size-base);`);
  root.push(`--hy-line-height: ${tokens.typography.lineHeight.latin};`);
  root.push(`--hy-line-height-tight: ${tokens.typography.lineHeight.tight};`);
  for (const [k, v] of Object.entries(tokens.space)) root.push(`--hy-space-${k}: ${px(v)};`);
  for (const [k, v] of Object.entries(tokens.size)) root.push(`--hy-size-${kebab(k)}: ${px(v)};`);
  root.push(`--hy-touch-target: var(--hy-size-touch-min);`);
  for (const [k, v] of Object.entries(tokens.radius)) root.push(`--hy-radius-${k}: ${px(v)};`);
  root.push(`--hy-radius: var(--hy-radius-md);`);
  for (const [k, v] of Object.entries(tokens.border)) root.push(`--hy-border-${kebab(k)}: ${px(v)};`);
  for (const [k, v] of Object.entries(tokens.zIndex)) root.push(`--hy-z-${kebab(k)}: ${v};`);
  for (const [k, v] of Object.entries(tokens.motion.duration)) root.push(`--hy-duration-${k}: ${ms(v)};`);
  root.push(`--hy-easing: ${tokens.motion.easing.standard};`);
  root.push("--hy-color-overlay: rgba(0, 0, 0, 0.5);");
  // Default density is touch; desktop is opt-in (vendor admin only).
  const dens = (d) => [
    `--hy-row-min-height: ${px(tokens.density[d].rowMinHeight)};`,
    `--hy-control-height: ${px(tokens.density[d].controlHeight)};`,
    `--hy-gap: ${px(tokens.density[d].gap)};`,
  ];
  root.push(...dens("touch"));

  const light = themeVars(tokens, "light");
  out.push(indented(':root,\n[data-theme="light"]', [...root, ...light]));
  out.push(indented('[data-density="touch"]', dens("touch")));
  out.push(indented('[data-density="desktop"]', dens("desktop")));
  out.push(
    "/* Coarse pointers always get touch hit areas (tokens.json density.desktop.note). */\n" +
      indented("@media (pointer: coarse)", [indented('[data-density="desktop"]', dens("touch"), "  ")]),
  );

  for (const theme of ["dark", "highContrast", "kds"]) {
    out.push(indented(`[data-theme="${theme}"]`, themeVars(tokens, theme)));
  }
  out.push(
    "/* Dark follows the OS until the user chooses a theme (no data-theme attribute). */\n" +
      indented("@media (prefers-color-scheme: dark)", [
        indented(":root:not([data-theme])", themeVars(tokens, "dark"), "  "),
      ]),
  );
  out.push(
    "/* High contrast uses strong 2 px borders. */\n" +
      indented('[data-theme="highContrast"]', ["--hy-border-width: var(--hy-border-width-strong);"]),
  );

  // Reduced motion: all durations become 0 (tokens.json motion.reducedMotion).
  const zero = Object.keys(tokens.motion.duration).map((k) => `--hy-duration-${k}: 0ms;`);
  out.push(
    indented("@media (prefers-reduced-motion: reduce)", [indented(":root", zero, "  ")]),
    indented('[data-reduce-motion="true"]', zero),
  );

  // Script-specific line height: Tamil and Malayalam glyph stacks need taller line boxes.
  out.push(
    indented(":lang(ta)", [`--hy-line-height: ${tokens.typography.lineHeight.ta};`]),
    indented(":lang(ml)", [`--hy-line-height: ${tokens.typography.lineHeight.ml};`]),
  );
  return `${out.join("\n\n")}\n`;
}

export function buildTs(tokens) {
  const themes = Object.keys(tokens.color.themes);
  return [
    "// GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand.",
    "",
    `export const tokens = ${JSON.stringify(tokens, null, 2)} as const;`,
    "",
    `export const themeNames = ${JSON.stringify(themes)} as const;`,
    "export type ThemeName = (typeof themeNames)[number];",
    "export type DensityName = keyof typeof tokens.density;",
    "export type SemanticColor = Exclude<keyof (typeof tokens.color.themes)[\"light\"], `_${string}`>;",
    "export type SyncState = Exclude<keyof typeof tokens.color.sync, `_${string}`>;",
    "export type Tokens = typeof tokens;",
    "",
  ].join("\n");
}

export function buildAll() {
  const tokens = JSON.parse(read("tokens/tokens.json"));
  return {
    "src/tokens/tokens.css": buildCss(tokens),
    "src/tokens/tokens.ts": buildTs(tokens),
  };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const files = buildAll();
  const check = process.argv.includes("--check");
  let stale = false;
  for (const [path, content] of Object.entries(files)) {
    if (check) {
      let current = "";
      try {
        current = read(path);
      } catch {
        /* missing counts as stale */
      }
      if (current !== content) {
        process.stderr.write(`stale: ${path} (run pnpm tokens)\n`);
        stale = true;
      }
    } else {
      writeFileSync(new URL(path, root), content);
      process.stdout.write(`wrote ${path}\n`);
    }
  }
  process.exit(stale ? 1 : 0);
}
